def _compute_adv_surrogate(self, adv_r: torch.Tensor, adv_c: torch.Tensor) -> torch.Tensor:
    """Adaptive barrier: combine advantages with smooth penalty scaling."""
    penalty = self._lagrangian_multiplier
    # Numerically stable: for large penalty, softplus(x) ≈ x
    if penalty > 20.0:
        effective_penalty = penalty
    else:
        effective_penalty = float(np.log1p(np.exp(penalty)))
    return (adv_r - effective_penalty * adv_c) / (1.0 + effective_penalty)
